sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?grandmother ?grandmotherName
WHERE {
  dbr:Gaston,_Duke_of_Orléans dbp:father dbr:Henry_IV_of_France .
  dbr:Henry_IV_of_France dbp:mother ?grandmother .
  OPTIONAL {
    ?grandmother rdfs:label ?grandmotherName .
    FILTER (lang(?grandmotherName) = "en")
  }
}
LIMIT 100

